import os
import sys

def solve():
    if os.path.exists("planting.in"):
        data = list(map(int, open("planting.in").read().split()))
    else:
        data = list(map(int, sys.stdin.read().split()))
    n = data[0]
    deg = [0] * (n + 1)
    idx = 1
    for _ in range(n - 1):
        u, v = data[idx], data[idx + 1]
        idx += 2
        deg[u] += 1
        deg[v] += 1
    ans = max(deg) + 1
    if os.path.exists("planting.in"):
        with open("planting.out", "w") as f:
            f.write(f"{ans}\n")
    else:
        print(ans)

if __name__ == "__main__":
    solve()

