#include <algorithm>
#include <cstdio>
#include <iostream>
#include <vector>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    if (FILE* f = fopen("planting.in", "r")) {
        fclose(f);
        freopen("planting.in", "r", stdin);
        freopen("planting.out", "w", stdout);
    }
    int n;
    cin >> n;
    vector<int> deg(n + 1, 0);
    int maxDeg = 0;
    for (int i = 0; i < n - 1; i++) {
        int u, v;
        cin >> u >> v;
        maxDeg = max(maxDeg, ++deg[u]);
        maxDeg = max(maxDeg, ++deg[v]);
    }
    cout << maxDeg + 1 << '\n';
    return 0;
}

